import { NextResponse } from "next/server";
import { eq } from "drizzle-orm";
import { db } from "@/db";
import { productFingerprints, products, stockMovements } from "@/db/schema";
import { buildDemoProducts } from "@/lib/demo-catalog";

export const dynamic = "force-dynamic";

/**
 * Loads a synthetic-but-real demo catalog. Every demo product has a descriptor
 * generated by the same vision engine the camera uses, so the detection pipeline
 * is exercised end to end even before a physical item is enrolled.
 */
export async function POST() {
  const demos = buildDemoProducts();
  let inserted = 0;
  let skipped = 0;

  for (const demo of demos) {
    const [existing] = await db.select().from(products).where(eq(products.sku, demo.spec.sku)).limit(1);
    if (existing) {
      skipped += 1;
      continue;
    }

    await db.transaction(async (tx) => {
      const [row] = await tx
        .insert(products)
        .values({
          sku: demo.spec.sku,
          name: demo.spec.name,
          category: demo.spec.category,
          priceCents: demo.spec.priceCents,
          costCents: demo.spec.costCents,
          stock: demo.spec.stock,
          lowStockThreshold: demo.spec.lowStockThreshold,
          barcode: demo.spec.barcode,
          imageData: demo.thumbnail,
        })
        .returning();

      await tx.insert(productFingerprints).values({
        productId: row.id,
        label: "demo render",
        descriptor: demo.descriptor,
        thumbnail: demo.thumbnail,
      });

      await tx.insert(stockMovements).values({
        productId: row.id,
        delta: demo.spec.stock,
        resultingStock: demo.spec.stock,
        reason: "initial",
        note: "Demo catalog load",
      });
    });
    inserted += 1;
  }

  return NextResponse.json({ ok: true, inserted, skipped, total: demos.length });
}
